-- VÉRTICE GESTÃO V3 - BANCO NOVO
create extension if not exists pgcrypto;

create table public.empresas(
 id uuid primary key default gen_random_uuid(), nome text not null default 'Vértice Marcenaria',
 cpf_cnpj text, telefone text, email text, endereco text, criado_em timestamptz not null default now()
);
create table public.perfis(
 user_id uuid primary key references auth.users(id) on delete cascade,
 empresa_id uuid not null references public.empresas(id) on delete cascade,
 nome text, papel text not null default 'comercial' check(papel in ('admin','comercial','financeiro')), ativo boolean not null default true, criado_em timestamptz default now()
);
create table public.clientes(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id),
 nome varchar(100) not null, cpf varchar(20), telefone varchar(20), email varchar(100), cep varchar(15), endereco varchar(200), numero varchar(20), complemento varchar(100), cidade varchar(100), uf varchar(2),
 observacoes text, criado_em timestamptz default now()
);
create table public.crm_leads(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), cliente_id bigint references public.clientes(id),
 nome text not null, telefone text, email text, origem text, ambiente_interesse text, descricao_projeto text, classificacao varchar(1) check(classificacao in ('A','B','C','D')),
 faixa_investimento text, prazo_compra text, valor_potencial numeric(12,2) default 0, etapa text not null default 'Novo Lead', status text not null default 'Ativo',
 motivo_perda text, observacoes text, proxima_acao text, proximo_contato_em timestamptz, ultimo_contato_em timestamptz,
 projeto_definido boolean default false, possui_medidas boolean default false, imovel_disponivel boolean default false, prazo_definido boolean default false,
 investimento_compativel boolean default false, solicitou_orcamento boolean default false, aceitou_medicao boolean default false, responde_contatos boolean default false, somente_pesquisa_preco boolean default false,
 responsavel_id uuid references auth.users(id), criado_por uuid default auth.uid(), data_fechamento date, criado_em timestamptz default now(), atualizado_em timestamptz default now()
);
create table public.chapas_mdf(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), nome_modelo varchar(100) not null, marca varchar(50), fornecedor varchar(100), preco_custo numeric(12,2) not null default 0, ativo boolean default true, criado_em timestamptz default now()
);
create table public.ferragens(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), tipo varchar(50) not null, nome_modelo varchar(100) not null, marca varchar(50), fornecedor varchar(100), preco_custo numeric(12,2) not null default 0, ativo boolean default true, criado_em timestamptz default now()
);
create table public.custos_operacionais(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), nome text not null,
 unidade text not null check(unidade in ('hora','dia','unidade','km','metro','fixo','percentual')), valor numeric(12,4) not null default 0,
 categoria text default 'Operacional', descricao text, ativo boolean not null default true, incluir_automaticamente boolean default false, ordem integer default 0, criado_em timestamptz default now()
);
create table public.config_global(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), chave varchar(50) not null, valor numeric(12,4) not null, unique(empresa_id,chave)
);
create table public.orcamentos(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), lead_id bigint references public.crm_leads(id), cliente_id bigint references public.clientes(id),
 cliente_nome text, cliente_cpf text, cliente_telefone text, cliente_email text, cliente_cep text, cliente_endereco text, cliente_numero text, cliente_cidade text, cliente_uf text,
 projeto varchar(150) not null, ambiente text, descricao_cliente text, observacoes_internas text, observacoes_cliente text,
 dias_trabalho numeric(8,2) default 0, quantidade_pessoas integer default 1, valor_dia_pessoa numeric(12,2) default 0, valor_montagem numeric(12,2) default 0,
 km_entrega numeric(10,2) default 0, horas_3d numeric(10,2) default 0, prazo_entrega_dias integer, validade_dias integer default 15, condicoes_pagamento text,
 custo_producao numeric(12,2) not null default 0, valor_lucro numeric(12,2) not null default 0, preco_final numeric(12,2) not null default 0, reinvestimento_materials numeric(12,2) default 0,
 margem_lucro numeric(7,2), detalhes_calculo jsonb not null default '{}'::jsonb, status varchar(30) default 'Rascunho',
 criado_por uuid default auth.uid(), data_criacao timestamptz default now(), atualizado_em timestamptz default now()
);
create table public.orcamento_itens(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), orcamento_id bigint not null references public.orcamentos(id) on delete cascade,
 tipo text not null, referencia_id bigint, descricao text not null, quantidade numeric(12,3) default 1, unidade text, valor_unitario numeric(12,2) default 0, valor_total numeric(12,2) default 0,
 exibir_cliente boolean default false, ordem integer default 0
);
create table public.orcamento_custos(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), orcamento_id bigint not null references public.orcamentos(id) on delete cascade,
 custo_operacional_id bigint references public.custos_operacionais(id), descricao text not null, unidade text, quantidade numeric(12,3) default 1, valor_unitario numeric(12,4) default 0, valor_total numeric(12,2) default 0
);
create table public.crm_interacoes(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), lead_id bigint references public.crm_leads(id) on delete cascade, cliente_id bigint references public.clientes(id),
 orcamento_id bigint references public.orcamentos(id), canal text not null, resultado text, descricao text, data_interacao timestamptz default now(), criado_por uuid default auth.uid()
);
create table public.crm_tarefas(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), lead_id bigint references public.crm_leads(id) on delete cascade, cliente_id bigint references public.clientes(id),
 orcamento_id bigint references public.orcamentos(id), tipo text default 'Follow-up', titulo text not null, descricao text, vencimento timestamptz not null, prioridade text default 'Normal',
 status text default 'Pendente', responsavel_id uuid references auth.users(id), criado_por uuid default auth.uid(), criado_em timestamptz default now()
);
create table public.auditoria(
 id bigint generated by default as identity primary key, empresa_id uuid not null references public.empresas(id), user_id uuid default auth.uid(), entidade text not null, entidade_id text, acao text not null, detalhes jsonb default '{}'::jsonb, criado_em timestamptz default now()
);
create index idx_leads_empresa_etapa on public.crm_leads(empresa_id,etapa);
create index idx_tarefas_empresa_vencimento on public.crm_tarefas(empresa_id,vencimento);
create index idx_orcamentos_empresa_status on public.orcamentos(empresa_id,status);
